<?php
require 'config.php';require_login();verify_csrf();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$path=upload_file('document',['pdf','jpg','jpeg','png'],'compliance');$s=db()->prepare("INSERT INTO compliance_documents(subject_type,subject_id,document_type,document_no,issue_date,expiry_date,file_path,notes) VALUES(?,?,?,?,?,?,?,?)");$s->execute([$_POST['subject_type'],(int)$_POST['subject_id'],$_POST['document_type'],$_POST['document_no'],$_POST['issue_date']?:null,$_POST['expiry_date']?:null,$path,$_POST['notes']]);flash('success','Compliance document saved.');redirect('compliance.php');}catch(Throwable $e){$error=$e->getMessage();}}
$drivers=db()->query("SELECT id,first_name, last_name FROM drivers")->fetchAll();$trucks=db()->query("SELECT id,unit_no FROM trucks")->fetchAll();$rows=db()->query("SELECT * FROM compliance_documents ORDER BY expiry_date ASC")->fetchAll();$pageTitle='Compliance';$active='compliance';require 'partials_header.php';?>
<div class="page-head"><div><h1>Driver & truck compliance</h1><p>Store licenses, medical cards, insurance, registrations and expiration dates.</p></div></div><div class="form-card" style="margin-bottom:20px"><h3>Add compliance record</h3><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field"><label>Subject type</label><select name="subject_type" id="subject_type" onchange="document.getElementById('driver_opts').style.display=this.value==='Driver'?'block':'none';document.getElementById('truck_opts').style.display=this.value==='Truck'?'block':'none'"><option>Driver</option><option>Truck</option></select></div><div class="field"><label>Driver</label><select name="subject_id" id="driver_opts"><?php foreach($drivers as $d):?><option value="<?=$d['id']?>"><?=e($d['first_name'].' '.$d['last_name'])?></option><?php endforeach;?></select><select id="truck_opts" style="display:none" name="truck_subject_id" onchange="document.querySelector('[name=subject_id]').value=this.value"><?php foreach($trucks as $t):?><option value="<?=$t['id']?>"><?=e($t['unit_no'])?></option><?php endforeach;?></select></div><div class="field"><label>Document type</label><input name="document_type" required placeholder="CDL, Medical Card, Insurance..."></div><div class="field"><label>Document number</label><input name="document_no"></div><div class="field"><label>Issue date</label><input type="date" name="issue_date"></div><div class="field"><label>Expiry date</label><input type="date" name="expiry_date"></div><div class="field"><label>Document file</label><input type="file" name="document" accept=".pdf,.jpg,.jpeg,.png"></div><div class="field"><label>Notes</label><input name="notes"></div></div><div class="form-actions"><button class="btn primary">Save compliance record</button></div></form></div><div class="table-wrap"><table class="table"><thead><tr><th>Type</th><th>Subject ID</th><th>Document</th><th>Number</th><th>Expiry</th><th>Status</th><th>File</th></tr></thead><tbody><?php foreach($rows as $r):$expired=$r['expiry_date']&&$r['expiry_date']<date('Y-m-d');$soon=$r['expiry_date']&&$r['expiry_date']<=date('Y-m-d',strtotime('+30 days'));?><tr><td><?=e($r['subject_type'])?></td><td><?=e($r['subject_id'])?></td><td><?=e($r['document_type'])?></td><td><?=e($r['document_no'])?></td><td><?=e($r['expiry_date']??'—')?></td><td><span class="badge <?=$expired?'red':($soon?'amber':'green')?>"><?=$expired?'Expired':($soon?'Expiring soon':'Current')?></span></td><td><?php if($r['file_path']):?><a href="<?=e($r['file_path'])?>" target="_blank">Open</a><?php else:?>—<?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" class="empty">No compliance records yet.</td></tr><?php endif;?></tbody></table></div><?php require 'partials_footer.php';?>